create extension if not exists pgcrypto;
create table if not exists public.profiles(id uuid primary key references auth.users(id) on delete cascade,display_name text,role text not null default 'user' check(role in ('user','admin')),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.settings(id bigint generated by default as identity primary key,"group" text not null,name text not null,locked boolean not null default false,payload jsonb not null default '{}'::jsonb,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique("group",name));
create table if not exists public.pages(id bigint generated by default as identity primary key,title varchar(60) not null,"metaDescription" varchar(155) not null,"metaKeywords" text,"noIndex" boolean not null default false,slug text unique not null,label varchar(60) not null,location text not null default 'navbar',"topAd" boolean,"bottomAd" boolean,"showShareButtons" boolean,content text not null,published_at date,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.posts(id bigint generated by default as identity primary key,title varchar(60) not null,"metaDescription" varchar(155) not null,"metaKeywords" text,thumbnail text,snippet text not null,"topAd" boolean,"bottomAd" boolean,"showShareButtons" boolean,content text not null,slug text unique not null,published_at date,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.views(id bigint generated by default as identity primary key,viewable_type text not null,viewable_id bigint not null,visitor text,collection text,viewed_at timestamptz not null default now());
create index if not exists views_viewable_idx on public.views(viewable_type,viewable_id);
create table if not exists public.views_counters(id bigint generated by default as identity primary key,identifier text not null,title text not null,views bigint not null default 0,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.converts_counters(id bigint generated by default as identity primary key,count bigint not null default 0,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.converter_formats(id bigint generated by default as identity primary key,slug text unique not null,title text not null,description text,enabled boolean not null default true,sort_order integer not null default 0,settings jsonb not null default '{}'::jsonb,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.conversions(id uuid primary key default gen_random_uuid(),user_id uuid references auth.users(id) on delete set null,source_name text not null,source_format text,target_format text not null,status text not null default 'queued' check(status in ('queued','processing','completed','failed')),input_size bigint,output_size bigint,error_message text,created_at timestamptz not null default now(),completed_at timestamptz);
create index if not exists conversions_created_idx on public.conversions(created_at desc);
create index if not exists conversions_user_idx on public.conversions(user_id);
insert into public.converter_formats(slug,title,description,sort_order) values
('ai','Image to AI','Convert any image to AI format',1),('apng','Image to APNG','Convert any image to APNG format',2),('avif','Image to AVIF','Convert any image to AVIF format',3),('bmp','Image to BMP','Convert any image to BMP format',4),('dds','Image to DDS','Convert any image to DDS format',5),('dib','Image to DIB','Convert any image to DIB format',6),('eps','Image to EPS','Convert any image to EPS format',7),('gif','Image to GIF','Convert any image to GIF format',8),('hdr','Image to HDR','Convert any image to HDR format',9),('heic','Image to HEIC','Convert any image to HEIC format',10),('heif','Image to HEIF','Convert any image to HEIF format',11),('ico','Image to ICO','Convert any image to ICO format',12),('jp2','Image to JP2','Convert any image to JP2 format',13),('jpe','Image to JPE','Convert any image to JPE format',14),('jpeg','Image to JPEG','Convert any image to JPEG format',15),('pdf','Image to PDF','Convert any image to PDF format',16),('png','Image to PNG','Convert any image to PNG format',17),('psd','Image to PSD','Convert any image to PSD format',18),('raw','Image to RAW','Convert any image to RAW format',19),('svg','Image to SVG','Convert any image to SVG format',20),('tga','Image to TGA','Convert any image to TGA format',21),('tiff','Image to TIFF','Convert any image to TIFF format',22),('wbmp','Image to WBMP','Convert any image to WBMP format',23),('webp','Image to WEBP','Convert any image to WEBP format',24)
on conflict(slug) do nothing;
alter table public.profiles enable row level security;
alter table public.settings enable row level security;
alter table public.pages enable row level security;
alter table public.posts enable row level security;
alter table public.views enable row level security;
alter table public.views_counters enable row level security;
alter table public.converts_counters enable row level security;
alter table public.converter_formats enable row level security;
alter table public.conversions enable row level security;
create policy "profiles self read" on public.profiles for select to authenticated using((select auth.uid())=id);
create policy "admin profiles read" on public.profiles for select to authenticated using(exists(select 1 from public.profiles p where p.id=(select auth.uid()) and p.role='admin'));
create policy "public enabled formats" on public.converter_formats for select to anon,authenticated using(enabled=true);
create policy "admin manage formats" on public.converter_formats for all to authenticated using(exists(select 1 from public.profiles p where p.id=(select auth.uid()) and p.role='admin')) with check(exists(select 1 from public.profiles p where p.id=(select auth.uid()) and p.role='admin'));
create policy "public published pages" on public.pages for select to anon,authenticated using(published_at is not null and published_at<=current_date);
create policy "admin manage pages" on public.pages for all to authenticated using(exists(select 1 from public.profiles p where p.id=(select auth.uid()) and p.role='admin')) with check(exists(select 1 from public.profiles p where p.id=(select auth.uid()) and p.role='admin'));
create policy "public published posts" on public.posts for select to anon,authenticated using(published_at is not null and published_at<=current_date);
create policy "admin manage posts" on public.posts for all to authenticated using(exists(select 1 from public.profiles p where p.id=(select auth.uid()) and p.role='admin')) with check(exists(select 1 from public.profiles p where p.id=(select auth.uid()) and p.role='admin'));
create policy "users insert conversions" on public.conversions for insert to anon,authenticated with check(user_id is null or user_id=(select auth.uid()));
create policy "users own conversions" on public.conversions for select to authenticated using((select auth.uid())=user_id);
create policy "users update own conversions" on public.conversions for update to authenticated using((select auth.uid())=user_id) with check((select auth.uid())=user_id);
create policy "admin conversions" on public.conversions for all to authenticated using(exists(select 1 from public.profiles p where p.id=(select auth.uid()) and p.role='admin')) with check(exists(select 1 from public.profiles p where p.id=(select auth.uid()) and p.role='admin'));
create policy "counter insert" on public.converts_counters for insert to anon,authenticated with check(true);
create policy "counter select" on public.converts_counters for select to anon,authenticated using(true);
create or replace function public.increment_convert_counter() returns void language plpgsql security invoker set search_path=public as $$begin insert into public.converts_counters(count) values(1); end;$$;
revoke all on function public.increment_convert_counter() from public;
grant execute on function public.increment_convert_counter() to anon,authenticated;
create or replace function public.handle_new_user() returns trigger language plpgsql security invoker set search_path=public as $$begin insert into public.profiles(id,display_name) values(new.id,coalesce(new.raw_user_meta_data->>'name',new.email)); return new; end;$$;
drop trigger if exists on_auth_user_created on auth.users;
create trigger on_auth_user_created after insert on auth.users for each row execute function public.handle_new_user();
grant select on public.converter_formats,public.pages,public.posts,public.converts_counters to anon,authenticated;
grant select,insert,update on public.conversions to authenticated;
do $$begin if not exists(select 1 from pg_publication_tables where pubname='supabase_realtime' and schemaname='public' and tablename='converter_formats') then alter publication supabase_realtime add table public.converter_formats; end if; if not exists(select 1 from pg_publication_tables where pubname='supabase_realtime' and schemaname='public' and tablename='conversions') then alter publication supabase_realtime add table public.conversions; end if;end$$;